create or replace view public.buildpulse_localization_coverage as
with locales(locale) as(select unnest(array['en','de','fr','tr','es','it','pt','ru','pl','nl','sv','no','fi','da','ro','hu','cs','el','bg','uk','zh','ja','ko','ar','hi']::text[])),verified as(select count(*)::bigint total from public.buildpulse_stories where verification_state='verified' and coalesce(publication_state,'active')<>'withheld')
select l.locale,v.total verified_stories,count(sl.id)::bigint localized_rows,count(sl.id) filter(where sl.translation_state='review')::bigint review_rows,count(sl.id) filter(where sl.translation_state='published')::bigint published_rows,case when v.total=0 then 0 else round(count(sl.id)::numeric*100/v.total,2) end coverage_pct from locales l cross join verified v left join public.buildpulse_story_localizations sl on sl.locale=l.locale group by l.locale,v.total;revoke all on public.buildpulse_localization_coverage from anon,authenticated;grant select on public.buildpulse_localization_coverage to service_role;